       ((MZ^2 - MW^2*\[Xi]w)*(-(MW^2*\[Xi]w) + MZ^2*\[Xi]z)) - 
      ((-1 + \[Xi]w)*\[Xi]z*sorttad[{MW, MZ*Sqrt[\[Xi]z], MW}, {1, 1, 1}])/
       ((-1 + \[Xi]z)*(-MW^2 + MZ^2*\[Xi]z)*(-(MW^2*\[Xi]w) + MZ^2*\[Xi]z)) - 
      (\[Xi]w*sorttad[{MW*Sqrt[\[Xi]w], MW, MW}, {1, 1, 1}])/
       ((MW - MZ)*(MW + MZ)*(MW^2 - MZ^2*\[Xi]z)) - 
      ((-1 + \[Xi]w)*\[Xi]w*sorttad[{MW*Sqrt[\[Xi]w], MZ, MW}, {1, 1, 1}])/
       ((MW - MZ)*(MW + MZ)*(-MZ^2 + MW^2*\[Xi]w)*(-1 + \[Xi]z)) + 
      (\[Xi]w^2*sorttad[{MW*Sqrt[\[Xi]w], MW*Sqrt[\[Xi]w], MW}, {1, 1, 1}])/
       ((MZ^2 - MW^2*\[Xi]w)*(-(MW^2*\[Xi]w) + MZ^2*\[Xi]z)) + 
      ((-1 + \[Xi]w)*\[Xi]w*\[Xi]z*sorttad[{MW*Sqrt[\[Xi]w], MZ*Sqrt[\[Xi]z], 
          MW}, {1, 1, 1}])/((-1 + \[Xi]z)*(-MW^2 + MZ^2*\[Xi]z)*
        (-(MW^2*\[Xi]w) + MZ^2*\[Xi]z))))/
    (2048*d*(-1 + QFTSymbols`MW^2/MZ^2)^2*Pi^8*(-1 + \[Xi]w)^2))
